PRAGMA foreign_keys=OFF;

ALTER TABLE content_items RENAME TO content_items_before_articles;

CREATE TABLE content_items (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  kind TEXT NOT NULL CHECK (kind IN ('projects','experiences','education','certifications','skills','socials','documents','articles')),
  slug TEXT NOT NULL,
  data TEXT NOT NULL DEFAULT '{}',
  sort_order INTEGER NOT NULL DEFAULT 0,
  visible INTEGER NOT NULL DEFAULT 1,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE(kind, slug)
);

SELECT id,kind,slug,data,sort_order,visible,created_at,updated_at FROM content_items_before_articles;
DROP TABLE content_items_before_articles;
CREATE INDEX idx_content_kind_order ON content_items(kind, sort_order, id);

-- Projects are replaced as a deliberate editorial set. Items in which Gökçe
-- had no role are omitted rather than presented as company-wide work.
DELETE FROM content_items WHERE kind='projects';


-- Restore the Everion experience removed by migration 005, with contribution
-- language that does not imply people management.
DELETE FROM content_items WHERE kind='experiences' AND slug IN ('software-engineer','everion-lead','everion-engineer');

DELETE FROM content_items WHERE kind='certifications';

DELETE FROM content_items WHERE kind='articles';

ON CONFLICT(key) DO UPDATE SET value=excluded.value,updated_at=CURRENT_TIMESTAMP;

PRAGMA foreign_keys=ON;
